sect1.example:
  Logical operators को प्रयोग


<?php

// --------------------
// यी operators short-circuit हुने भएकाले foo() कहिल्यै call हुँदैन

$a = (false && foo());
$b = (true  || foo());
$c = (false and foo());
$d = (true  or  foo());

// --------------------
// "||" को प्राथमिकता "or" भन्दा बढी हुन्छ

// (false || true) को नतिजा $e मा assign हुन्छ
$e = false || true;

// "or" operation हुनु अघि नै false मान $f मा assign हुन्छ
$f = false or true;

var_dump($e, $f);

// --------------------
// "&&" को प्राथमिकता "and" भन्दा बढी हुन्छ

$g = true && false;
$h = true and false;

var_dump($g, $h);
?>


  &example.outputs.similar;


bool(true)
bool(false)
bool(false)
bool(true)
